{
  "API_calls": [],
  "collected_information": {
    "environment_setup": {
      "python_version": ">=3.10 and <3.13",
      "installation": {
        "basic": "pip install crewai",
        "with_optional_features": "pip install 'crewai[tools]'"
      },
      "dependency_management": {
        "tool": "UV",
        "commands": ["uv lock", "uv sync", "uv venv"]
      },
      "troubleshooting": {
        "missing_tiktoken_module": [
          "pip install 'crewai[embeddings]'",
          "pip install 'crewai[tools]'"
        ],
        "rust_compiler_required": true,
        "windows_build_tools": "Visual C++ Build Tools needed for building wheels",
        "pip_upgrade_command": "pip install --upgrade pip",
        "use_prebuilt_wheel": "pip install tiktoken --prefer-binary"
      },
      "environment_variables": [ "OPENAI_API_KEY", "SERPER_API_KEY" ],
      "env_file": ".env"
    },
    "running_tests": {
      "install_pre_commit_hooks": "pre-commit install",
      "run_tests": "uv run pytest .",
      "run_type_checks": "uvx mypy src"
    }
  },
  "terminate": true
}
